import{z as s,x as m,o as l,c as A,q as r,j as o,D as e,d as E,s as p,S as d,b as i}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"权重加载与流式","description":"","frontmatter":{"title":"权重加载与流式","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/weight-loading-streaming.md","filePath":"llm/weight-loading-streaming.md","lastUpdated":1791063341000}'),n={name:"llm/weight-loading-streaming.md"};function B(c,a,P,h,C,D){const t=m("Mermaid");return l(),A("div",null,[a[2]||(a[2]=r('<h1 id="权重加载与流式" tabindex="-1">权重加载与流式 <a class="header-anchor" href="#权重加载与流式" aria-label="Permalink to &quot;权重加载与流式&quot;">​</a></h1><div class="epigraph"><p>启动延迟是把百 GB 权重量进设备内存的时间；能 mmap 的量化块可以边用边页入，但 decode 热路径上的缺页会变成逐步抖动。</p><footer>—— 对照 llama.cpp 对 GGUF 的 mmap，以及 Hugging Face 加速库按 device_map 分片加载；容器格式见下一课 safetensors</footer></div><p><a href="/llm/embedding-serving">上一课</a>的模型往往小到一次加载可忽略。LLM 服务的冷启动、扩容、换 LoRA 基座，都是 <em>把权重从盘送到 HBM</em>。本课写加载策略：一次性拷贝、内存映射、分层流式、以及与量化的关系。<a href="/llm/llamacpp">llama.cpp</a> 用 mmap 让操作系统页入 GGUF 块；GPU 服务通常要 cudaMemcpy 或 GDS。下一课专写 safetensors 为什么替代 pickle。本课不把格式当主角，当传输与驻留。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(W_{\\mathrm{bytes}}\\) 在会计里是逐步要读的常数；启动时还要付一次把它放进设备的时间。70B 半精度约 140GB 量级，从网络盘加载可以分钟计，扩容 SLA 破掉。缺口是：驻留策略（全驻 HBM、CPU 卸载、分层流式）与 <em>缺页是否落在 decode 热路径</em>。mmap 在 CPU 推理上自然；GPU 上若内核假设指针常驻 HBM，缺页或不完整拷贝就是错误或巨大抖动。</p><p><span class="marginnote">数字实例：140 GB 权重走 PCIe 4.0 x16（单向约 32 GB/s），理想情况也要约 4.4 秒搬完；若从对象存储按 1–2 GB/s 拉，冷启动就以分钟计。扩容等 5 分钟和等 2 分钟，SLA 是两种命运——这就是启动账单不能只算 HBM 带宽的原因。</span></p><p>流式加载：先把第 1 层送上 GPU 即可开始 prefill 的第一层，与后续层拷贝重叠。依赖是层序。TP 下每卡只加载分片，体积除以 TP，但要同步对齐。</p><p><span class="marginnote">量化后 \\(W\\) 变小，加载与逐步带宽双赢。GPTQ 权重要么预量化在文件里直接加载，要么先加载 FP16 再量化——后者把启动峰值显存顶回 FP16，常 OOM。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生产 GPU 服务：预热时完整加载，CUDA Graph / 核假设常驻。扩容用本地 SSD 缓存分片，避免每次从对象存储拉。CPU/GPU 混合：热层驻 GPU，冷层驻主机，decode 每步可能触发拷贝，TPOT 抖动——只适合内存不够的折中。llama.cpp 路径：mmap GGUF，decode 核直接读量化块，缺页由 OS 处理，适合单用户本地，不适合多租户 SLA。</p><p><span class="marginnote">mmap（内存映射）可译成「懒加载的文件视图」：程序宣布「这文件就当我的内存用」，操作系统只在真正摸到某一页时才把那块从盘读进来。llama.cpp 借它做到「打开上百 GB 的模型文件却不占上百 GB 内存」，代价是每次摸到没读过的块会卡一下，这个卡就是缺页。</span></p><p>与 LoRA：基座常驻，适配器热插拔加载体积小。多适配器不要每请求重载基座。</p>',12)),(l(),o(d,null,{default:e(()=>[p(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DISK%5B%22%E7%9B%98%E4%B8%8A%E5%88%86%E7%89%87%22%5D%20--%3E%20POL%5B%22%E7%AD%96%E7%95%A5%22%5D%0A%20%20POL%20--%3E%20FULL%5B%22%E9%A2%84%E7%83%AD%E5%85%A8%E9%A9%BB%20HBM%22%5D%0A%20%20POL%20--%3E%20STRM%5B%22%E6%8C%89%E5%B1%82%E6%B5%81%E5%BC%8F%E4%B8%8E%E8%AE%A1%E7%AE%97%E9%87%8D%E5%8F%A0%22%5D%0A%20%20POL%20--%3E%20MMAP%5B%22CPU%20mmap%20%E9%87%8F%E5%8C%96%E5%9D%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[E("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"加载带宽受盘、PCIe、PCIe 到 GPU 限制，往往低于 HBM。流式重叠把启动从「拷完再算」变成 max(拷, 前几层计算)，对长 prefill 有用。decode 开始后若仍在流后面的层，会与逐步抢 PCIe。应在 decode 前完成驻留，或明确接受抖动。",-1)),(l(),o(d,null,{default:e(()=>[p(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22%E5%90%AF%E5%8A%A8%3A%20%E5%8F%AA%E6%8B%B7%E7%AC%AC%201%20%E5%B1%82%22%5D%20--%3E%20P1%5B%22prefill%20%E9%A6%96%E5%B1%82%E5%BC%80%E5%A7%8B%E8%AE%A1%E7%AE%97%22%5D%0A%20%20T0%20--%3E%20BG%5B%22%E5%90%8E%E5%8F%B0%E7%BB%A7%E7%BB%AD%E6%8B%B7%E7%AC%AC%202..N%20%E5%B1%82%22%5D%0A%20%20P1%20--%3E%20OV%5B%22%E6%8B%B7%E8%B4%9D%E4%B8%8E%E8%AE%A1%E7%AE%97%E9%87%8D%E5%8F%A0%22%5D%0A%20%20BG%20--%3E%20OV%0A%20%20OV%20--%3E%20DE%5B%22decode%20%E5%BC%80%E5%A7%8B%22%5D%0A%20%20DE%20--%3E%20Q%7B%22%E5%90%8E%E9%9D%A2%E7%9A%84%E5%B1%82%E6%8B%B7%E5%AE%8C%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20SM%5B%22HBM%20%E5%B8%B8%E9%A9%BB%2C%20%E9%80%90%E6%AD%A5%E7%A8%B3%E5%AE%9A%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20JT%5B%22%E4%B8%8E%20decode%20%E6%8A%A2%20PCIe%20%E2%86%92%20TPOT%20%E6%8A%96%E5%8A%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">直觉类比：流式加载像餐厅客人一点菜就一道道上，而不是等全部菜做完才开饭——prefill 是第一位客人，第 1 层权重上桌就能开工。但 decode 阶段每写一个字都要「下一口」，若厨房（PCIe）还在赶制后面的菜，上菜速度就会忽快忽慢，这就是抖动。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在 GPU 热路径上对网络文件系统 mmap。不要边 decode 边从对象存储拉层。下一课：文件格式如何让加载既快又不执行任意代码。</p><p>出处：llama.cpp / GGUF 加载行为；Hugging Face <code>accelerate</code> device_map。不发明论文号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>冷启动账单是 \\(W_{\\mathrm{bytes}}\\) 过盘与 PCIe；量化同时减启动与逐步 IO。</li><li>GPU 服务应预热常驻；mmap 适合本地 CPU 路径。</li><li>按层流式可与 prefill 重叠，decode 前应结束。</li><li>TP 加载分片；LoRA 不要重载基座。</li><li>预量化文件直接加载，避免 FP16 峰值。</li><li>下一课：safetensors 格式。</li><li>出处：llama.cpp；HF accelerate。</li></ul>',6))])}const _=s(n,[["render",B]]);export{g as __pageData,_ as default};
